pragma solidity ^0.8.36;
contract A { function f() public virtual returns(uint) { return 1; } } abstract contract B { function f() public virtual returns(uint); } contract C is A, B { function f() public override(A,B) returns(uint) { return super.f(); } }
contract X { function f(bool x) public virtual returns(uint) { return x ? 1 : 2; } function f(uint x) public virtual returns(uint) { return x; } } abstract contract Y { function f(uint x) public virtual returns(uint); } contract Z is X, Y { function f(uint x) public override(X,Y) returns(uint) { return super.f(x); } }
